mapper.select:
SELECT  FROM kb_knowledge_gap g
WHERE  AND

    g.reporter_user_id = #{actor}
    g.assignee_user_id = #{actor} AND 

    FALSE

AND g.state = #{status}
AND g.id < #{beforeId}
ORDER BY g.id DESC LIMIT #{limit}

SELECT e.event_id, e.gap_id, e.kind, e.result_version, e.actor_user_id, e.assignee_user_id,
    e.assignment_epoch, e.entry_id, e.solution_id, e.occurred_at
FROM kb_knowledge_gap_event e JOIN kb_knowledge_gap g ON g.id = e.gap_id
WHERE g.id = #{gapId} AND 
AND e.result_version > #{afterVersion}
ORDER BY e.result_version ASC LIMIT #{limit}

SELECT request_id, actor_user_id, operation, gap_id, expected_version, input_digest,
    result_gap_id, result_version, result_state, result_event_id, result_solution_id
FROM kb_knowledge_gap_command WHERE request_id = #{requestId}
